from types import SimpleNamespace

def create_instance(objcls, settings, crawler, *args, **kwargs):
    """Construct a class instance using its ``from_crawler`` or
    ``from_settings`` constructors, if available.

    At least one of ``settings`` and ``crawler`` needs to be different from
    ``None``. If ``settings `` is ``None``, ``crawler.settings`` will be used.
    If ``crawler`` is ``None``, only the ``from_settings`` constructor will be
    tried.

    ``*args`` and ``**kwargs`` are forwarded to the constructors.

    Raises ``ValueError`` if both ``settings`` and ``crawler`` are ``None``.
    """
    if settings is None:
        if crawler is None:
            raise ValueError("Specify at least one of settings and crawler.")
        settings = crawler.settings
    if crawler and hasattr(objcls, 'from_crawler'):
        return objcls.from_crawler(crawler, *args, **kwargs)
    elif hasattr(objcls, 'from_settings'):
        return objcls.from_settings(settings, *args, **kwargs)
    else:
        return objcls(*args, **kwargs)


def solve(methods, settings, crawler_settings, returns, args, kwargs):
    def result(method, source, arguments, keywords):
        if method in returns:
            return returns[method]
        return {"via": method, "source": source, "args": list(arguments), "kwargs": keywords}
    class Probe:
        def __new__(cls, *arguments, **keywords):
            return result("direct", None, arguments, keywords)
    if "settings" in methods:
        Probe.from_settings = classmethod(lambda cls, source, *a, **k: result("settings", source, a, k))
    if "crawler" in methods:
        Probe.from_crawler = classmethod(lambda cls, source, *a, **k: result("crawler", source.settings, a, k))
    crawler = None if crawler_settings is None else SimpleNamespace(settings=crawler_settings)
    return create_instance(Probe, settings, crawler, *args, **kwargs)
